import{_ as t,o,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Ceph Crimson / SeaStor OSD 2020-08-26","description":"","frontmatter":{"title":"Ceph Crimson / SeaStor OSD 2020-08-26","date":"2020-08-26T00:00:00.000Z","updated":"2020-08-26T00:00:00.000Z","tags":["Ceph","分布式存储","存储优化","技术测试","垃圾回收"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-08-26.md","filePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-08-26.md","lastUpdated":1780459816000}'),p={name:"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-08-26.md"};function l(s,e,a,n,_,d){return o(),r("div",null,[...e[0]||(e[0]=[i("<p>在本次会议中，Ceph项目的研发团队讨论了多个关键议题和技术进展：</p><ol><li><p><strong>技术进展</strong>：团队在上周进行了基于技术的测试，并取得了一些进展。解决了第一个恢复后视图错误，并对基本的OSD操作进行了测试。</p></li><li><p><strong>代码更新与实现</strong>：根据评论更新了extend map 3，并继续进行old map tree node的实现。</p></li><li><p><strong>垃圾回收与空间管理</strong>：正在开发垃圾回收功能，使用相同的extent rewrite机制。计划实施空间计费，以确定哪个段适合进行垃圾回收，并提出了一个简单的内存计数器策略来管理每个段中的活动字节数。</p></li><li><p><strong>中断处理</strong>：正在调试可中断的擦除未来（interruptible eraser future），发现中断机制比预期复杂，需要处理中断相关的错误。</p></li><li><p><strong>集成与测试</strong>：已将aerated future与事务菜单接口集成，并迁移单元测试到Google Test框架。正在集成cached extent逻辑，并研究lba map和lbht的实现。</p></li><li><p><strong>潜在的新技术</strong>：讨论了可能的异构存储引擎（如Micron），该引擎可能在未来用于替换现有的存储层。但该技术仍在开发中，特别是异步I/O支持尚未完成。</p></li></ol><p>会议决定：</p><ul><li>继续推进垃圾回收和空间管理功能的开发。</li><li>解决中断处理中的复杂问题，并确保其正确性。</li><li>探索和评估新的存储技术，如Micron，以备未来可能的集成。</li></ul><p>后续行动计划：</p><ul><li>完成old map tree node的实现。</li><li>继续调试和完善中断处理机制。</li><li>评估和测试新的存储技术，以确定其是否适合集成到现有系统中。</li><li>定期更新和维护extend map 3，确保其符合最新的需求和标准。</li></ul><p>会议还提到了网络问题和通信中断，需要确保后续会议的稳定性。对于新技术的探索，建议保持关注，但不应影响当前的主要开发任务。</p>",7)])])}const c=t(p,[["render",l]]);export{m as __pageData,c as default};
